# Standalone-app files: manifest + service worker + register snippet
import json,glob,os
os.makedirs('pwa',exist_ok=True)
json.dump({"name":"Puzzle Parlor","short_name":"Puzzles","start_url":"./index.html","scope":"./","display":"standalone","background_color":"#f3efe8","theme_color":"#f3efe8","icons":[{"src":"icon-192.png","sizes":"192x192","type":"image/png"},{"src":"icon-512.png","sizes":"512x512","type":"image/png","purpose":"maskable"}]},open('pwa/manifest.webmanifest','w'),indent=1)
open('pwa/sw.js','w').write("""const C='puzzle-parlor-v1';
self.addEventListener('install',e=>{e.waitUntil(caches.open(C).then(c=>c.addAll(['./','./index.html','./manifest.webmanifest'])));self.skipWaiting()});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==C).map(k=>caches.delete(k)))));self.clients.claim()});
self.addEventListener('fetch',e=>{if(e.request.method!=='GET')return;e.respondWith(caches.match(e.request).then(r=>r||fetch(e.request).then(res=>{if(res.ok&&new URL(e.request.url).origin===location.origin){const cp=res.clone();caches.open(C).then(c=>c.put(e.request,cp))}return res})))});
""")
# icons: generated by fav/gen.py (cream piece on gold)
print(os.listdir('pwa'))
